31:pub struct RunitSystemctlService {
32:    /// Base directory for Artix runit service definitions.
33:    sv_dir: String,
34:    /// Live/active runlevel directory scanned by runsvdir.
35:    runtime_dir: String,
36:    /// Persistent boot-enable directory for the `default` runlevel.
37:    enable_dir: String,
38:}
39:
40:impl RunitSystemctlService {
41:    pub fn new() -> Self {
42:        Self {
43:            sv_dir: RUNIT_SV_DIR.to_string(),
44:            runtime_dir: RUNIT_SERVICE_DIR.to_string(),
45:            enable_dir: RUNIT_RUNSVDIR_DEFAULT.to_string(),
46:        }
47:    }
48:
49:    /// Check if runit's `sv` control tool is available.
50:    fn check_runit_available(&self) -> bool {
51:        Command::new("sv").output().is_ok()
52:    }
53:
54:    fn def_path(&self, service: &str) -> String {
55:        format!("{}/{}", self.sv_dir, service)
56:    }
57:
58:    fn live_path(&self, service: &str) -> String {
59:        format!("{}/{}", self.runtime_dir, service)
60:    }
61:
62:    fn enable_link_path(&self, service: &str) -> String {
63:        format!("{}/{}", self.enable_dir, service)
64:    }
65:
66:    /// Symlink a service definition into a target directory if not already present.
67:    fn ensure_symlink(&self, service: &str, target_dir: &str) -> Result<(), String> {
68:        let def = self.def_path(service);
69:        if !std::path::Path::new(&def).exists() {
70:            return Err(format!("service {} not found in {}", service, self.sv_dir));
71:        }
72:        if let Err(e) = std::fs::create_dir_all(target_dir) {
73:            return Err(format!("failed to create {}: {}", target_dir, e));
74:        }
75:        let link = format!("{}/{}", target_dir, service);
76:        if std::path::Path::new(&link).exists() {
77:            return Ok(());
78:        }
79:        #[cfg(unix)]
80:        {
81:            std::os::unix::fs::symlink(&def, &link)
82:                .map_err(|e| format!("failed to symlink {} -> {}: {}", link, def, e))?;
83:        }
84:        Ok(())
85:    }
86:
87:    fn remove_symlink(&self, service: &str, target_dir: &str) -> Result<(), String> {
88:        let link = format!("{}/{}", target_dir, service);
89:        match std::fs::remove_file(&link) {
90:            Ok(()) => Ok(()),
91:            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
92:            Err(error) => Err(format!("Failed to remove {link}: {error}")),
93:        }
94:    }
95:
96:    fn validate_service_name(service: &str) -> Result<(), String> {
97:        if service.is_empty()
98:            || service.len() > 128
99:            || service == "."
100:            || service == ".."
101:            || !service.bytes().all(|byte| {
102:                byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-' | b'.' | b'@')
103:            })
104:        {
105:            return Err("invalid runit service name".to_string());
106:        }
107:        Ok(())
108:    }
109:
110:    /// Service lifecycle is a root-only system-bus boundary. Higher-level
111:    /// identities and capabilities are checked by op-grpc-bridge; this second
112:    /// gate prevents a local unprivileged process from skipping that path and
113:    /// invoking runit directly over D-Bus.
114:    async fn require_root_caller(
115:        connection: &Connection,
116:        header: &Header<'_>,
117:    ) -> Result<(), String> {
118:        let sender = header
119:            .sender()
120:            .ok_or_else(|| "D-Bus caller has no unique sender".to_string())?;
121:        let proxy = zbus::fdo::DBusProxy::new(connection)
122:            .await
123:            .map_err(|error| format!("D-Bus credential lookup unavailable: {error}"))?;
124:        let uid = proxy
125:            .get_connection_unix_user(sender.clone().into())
126:            .await
127:            .map_err(|error| format!("D-Bus caller credential lookup failed: {error}"))?;
128:        if uid != 0 {
129:            return Err("permission denied: service lifecycle requires uid 0".to_string());
130:        }
131:        Ok(())
132:    }
133:
134:    async fn authorize_lifecycle(
135:        service: &str,
136:        connection: &Connection,
137:        header: &Header<'_>,
138:    ) -> Result<(), String> {
139:        Self::validate_service_name(service)?;
140:        Self::require_root_caller(connection, header).await
141:    }
142:
143:    /// Execute `sv <args>` and return (success, output)
144:    fn run_sv(&self, args: &[&str]) -> (bool, String) {
145:        if !self.check_runit_available() {
146:            return (
147:                false,
148:                "runit tools not available. Is runit installed?".to_string(),
149:            );
150:        }
151:
152:        match Command::new("sv").args(args).output() {
153:            Ok(output) => {
154:                let stdout = String::from_utf8_lossy(&output.stdout).to_string();
155:                let stderr = String::from_utf8_lossy(&output.stderr).to_string();
156:
157:                if output.status.success() {
158:                    let result = if stdout.is_empty() { stderr } else { stdout };
159:                    (true, result.trim().to_string())
160:                } else {
161:                    let error = if stderr.is_empty() { stdout } else { stderr };
162:                    (false, error.trim().to_string())
163:                }
164:            }
165:            Err(e) => (false, format!("Failed to execute sv: {}", e)),
166:        }
167:    }
168:
169:    /// Execute `sv status <service>` and parse output
170:    fn run_sv_status(&self, service: &str) -> Result<ServiceStatus, String> {
171:        let path = self.live_path(service);
172:        match Command::new("sv").arg("status").arg(&path).output() {
173:            Ok(output) => {
174:                let stdout = String::from_utf8_lossy(&output.stdout);
175:                Ok(ServiceStatus::from_sv_status_output(&stdout, service))
176:            }
177:            Err(e) => Err(format!("Failed to execute sv status: {}", e)),
178:        }
179:    }
180:
181:    /// Check if a service is enabled (symlinked into the persistent `default` runlevel)
182:    fn is_service_enabled(&self, service: &str) -> bool {
183:        std::path::Path::new(&self.enable_link_path(service)).exists()
184:    }
185:}
